"""Tests for django.utils.decorators module."""

from functools import wraps

from django.test import SimpleTestCase


def my_decorator(func):
    """A simple decorator for testing."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper


def decorator_with_attr(func):
    """A decorator that adds an attribute."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper.custom_attr = "custom_value"
    return wrapper


class ClassOnlyMethodTests(SimpleTestCase):
    """Tests for classonlymethod class."""

    def test_classonlymethod_available_on_class(self):
        """Test that classonlymethod is available on the class."""
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classonlymethod
            def test_method(cls):
                return "success"

        self.assertEqual(TestClass.test_method(), "success")

    def test_classonlymethod_raises_on_instance(self):
        """Test that accessing classonlymethod on instance raises AttributeError."""
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classonlymethod
            def test_method(cls):
                return "success"

        obj = TestClass()
        with self.assertRaises(AttributeError) as context:
            obj.test_method()
        self.assertIn("available only on the class", str(context.exception))


class MultiDecorateTests(SimpleTestCase):
    """Tests for _multi_decorate function."""

    def test_multi_decorate_single_decorator(self):
        """Test _multi_decorate with a single decorator."""
        from django.utils.decorators import _multi_decorate

        class TestClass:
            def method(self):
                return "result"

        # Use _multi_decorate as a function, not a decorator
        decorated_method = _multi_decorate(my_decorator, TestClass.method)
        obj = TestClass()
        result = decorated_method(obj)
        self.assertEqual(result, "result")

    def test_multi_decorate_multiple_decorators(self):
        """Test _multi_decorate with multiple decorators."""
        from django.utils.decorators import _multi_decorate

        def another_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                result = func(*args, **kwargs)
                return f"wrapped_{result}"
            return wrapper

        class TestClass:
            def method(self):
                return "result"

        decorated_method = _multi_decorate([my_decorator, another_decorator], TestClass.method)
        obj = TestClass()
        result = decorated_method(obj)
        self.assertEqual(result, "wrapped_result")

    def test_multi_decorate_preserves_name(self):
        """Test that _multi_decorate preserves the method name."""
        from django.utils.decorators import _multi_decorate

        class TestClass:
            def my_method(self):
                return "result"

        decorated_method = _multi_decorate(my_decorator, TestClass.my_method)
        self.assertEqual(decorated_method.__name__, "my_method")


class MethodDecoratorTests(SimpleTestCase):
    """Tests for method_decorator function."""

    def test_method_decorator_on_function(self):
        """Test method_decorator applied to a function."""
        from django.utils.decorators import method_decorator

        @method_decorator(my_decorator)
        def my_func():
            return "result"

        # Note: method_decorator on standalone functions has special behavior
        # The key test is that it can be applied without raising an error
        self.assertTrue(callable(my_func))

    def test_method_decorator_on_class_method(self):
        """Test method_decorator applied to a class method."""
        from django.utils.decorators import method_decorator

        @method_decorator(my_decorator, name='my_method')
        class MyClass:
            def my_method(self):
                return "result"

        obj = MyClass()
        self.assertEqual(obj.my_method(), "result")

    def test_method_decorator_with_name_parameter(self):
        """Test method_decorator with name parameter on class."""
        from django.utils.decorators import method_decorator

        @method_decorator(my_decorator, name='my_method')
        class MyClass:
            def my_method(self):
                return "result"

        obj = MyClass()
        self.assertEqual(obj.my_method(), "result")

    def test_method_decorator_missing_name_raises_valueerror(self):
        """Test that missing name raises ValueError."""
        from django.utils.decorators import method_decorator

        with self.assertRaises(ValueError) as context:
            @method_decorator(my_decorator, name='nonexistent')
            class AnotherClass:
                pass

        self.assertIn("must be the name of a method", str(context.exception))

    def test_method_decorator_non_callable_raises_typeerror(self):
        """Test that decorating non-callable raises TypeError."""
        from django.utils.decorators import method_decorator

        # Create a class with a non-callable attribute first, then try to decorate it
        class MyClass:
            my_attr = "not callable"

        # Try to decorate the non-callable attribute on the same class
        with self.assertRaises(TypeError) as context:
            @method_decorator(my_decorator, name='my_attr')
            class MyClass:
                pass

        self.assertIn("isn't a callable attribute", str(context.exception))

    def test_method_decorator_preserves_attributes(self):
        """Test that method_decorator preserves decorator attributes."""
        from django.utils.decorators import method_decorator

        @method_decorator(decorator_with_attr, name='my_method')
        class MyClass:
            def my_method(self):
                return "result"

        obj = MyClass()
        self.assertTrue(hasattr(obj.my_method, 'custom_attr'))
        self.assertEqual(obj.my_method.custom_attr, "custom_value")


class MiddlewareDecoratorTests(SimpleTestCase):
    """Tests for middleware-related decorator functions."""

    def test_decorator_from_middleware_with_args_returns_function(self):
        """Test that decorator_from_middleware_with_args returns a function."""
        from django.utils.decorators import decorator_from_middleware_with_args

        class DummyMiddleware:
            def __init__(self, view_func, *args, **kwargs):
                self.view_func = view_func
                self.args = args
                self.kwargs = kwargs

        result = decorator_from_middleware_with_args(DummyMiddleware)
        self.assertTrue(callable(result))

    def test_decorator_from_middleware_returns_decorator(self):
        """Test that decorator_from_middleware returns a decorator."""
        from django.utils.decorators import decorator_from_middleware

        class DummyMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

        result = decorator_from_middleware(DummyMiddleware)
        self.assertTrue(callable(result))

    def test_make_middleware_decorator_basic(self):
        """Test make_middleware_decorator creates a decorator."""
        from django.utils.decorators import make_middleware_decorator

        class DummyMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

        decorator_factory = make_middleware_decorator(DummyMiddleware)
        self.assertTrue(callable(decorator_factory))

    def test_make_middleware_decorator_with_args(self):
        """Test make_middleware_decorator passes args to middleware."""
        from django.utils.decorators import make_middleware_decorator

        captured_args = []
        captured_kwargs = {}

        class DummyMiddleware:
            def __init__(self, view_func, *args, **kwargs):
                self.view_func = view_func
                captured_args.extend(args)
                captured_kwargs.update(kwargs)

        decorator_factory = make_middleware_decorator(DummyMiddleware)
        decorator = decorator_factory("arg1", kwarg="value1")
        decorated = decorator(lambda x: None)

        self.assertEqual(captured_args, ["arg1"])
        self.assertEqual(captured_kwargs, {"kwarg": "value1"})

    def test_make_middleware_decorator_process_request_none(self):
        """Test middleware process_request returning None continues execution."""
        from django.utils.decorators import make_middleware_decorator

        class ProcessRequestMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_request(self, request):
                return None

        decorator_factory = make_middleware_decorator(ProcessRequestMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            return "view_response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "view_response")

    def test_make_middleware_decorator_process_request_returns_value(self):
        """Test middleware process_request returning value short-circuits."""
        from django.utils.decorators import make_middleware_decorator

        class ProcessRequestMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_request(self, request):
                return "short_circuit_response"

        decorator_factory = make_middleware_decorator(ProcessRequestMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            return "view_response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "short_circuit_response")

    def test_make_middleware_decorator_process_view_returns_value(self):
        """Test middleware process_view returning value short-circuits."""
        from django.utils.decorators import make_middleware_decorator

        class ProcessViewMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_view(self, request, view_func, args, kwargs):
                return "process_view_response"

        decorator_factory = make_middleware_decorator(ProcessViewMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            return "view_response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "process_view_response")

    def test_make_middleware_decorator_process_exception_returns_value(self):
        """Test middleware process_exception returning value handles exception."""
        from django.utils.decorators import make_middleware_decorator

        class ProcessExceptionMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_exception(self, request, exception):
                return "exception_handled"

        decorator_factory = make_middleware_decorator(ProcessExceptionMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            raise ValueError("test error")

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "exception_handled")

    def test_make_middleware_decorator_process_response(self):
        """Test middleware process_response modifies response."""
        from django.utils.decorators import make_middleware_decorator

        class ProcessResponseMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_response(self, request, response):
                return f"modified_{response}"

        decorator_factory = make_middleware_decorator(ProcessResponseMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            return "original_response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "modified_original_response")

    def test_make_middleware_decorator_wraps_view_func(self):
        """Test that the wrapped view preserves original function metadata."""
        from django.utils.decorators import make_middleware_decorator

        class DummyMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

        decorator_factory = make_middleware_decorator(DummyMiddleware)
        decorator = decorator_factory()

        def original_view(request):
            """Original view docstring."""
            return "response"

        decorated = decorator(original_view)
        self.assertEqual(decorated.__name__, "original_view")
        self.assertEqual(decorated.__doc__, "Original view docstring.")


class SyncAsyncMiddlewareTests(SimpleTestCase):
