class MakeMiddlewareDecoratorEdgeCasesTests(SimpleTestCase):
    """Edge case tests for make_middleware_decorator."""

    def test_make_middleware_decorator_no_hooks(self):
        """Test middleware with no hook methods."""
        from django.utils.decorators import make_middleware_decorator

        class NoHooksMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

        decorator_factory = make_middleware_decorator(NoHooksMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            return "response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "response")

    def test_make_middleware_decorator_all_hooks(self):
        """Test middleware with all hook methods."""
        from django.utils.decorators import make_middleware_decorator

        class AllHooksMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_request(self, request):
                return None

            def process_view(self, request, view_func, args, kwargs):
                return None

            def process_exception(self, request, exception):
                return None

            def process_response(self, request, response):
                return f"processed_{response}"

        decorator_factory = make_middleware_decorator(AllHooksMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            return "response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "processed_response")

    def test_make_middleware_decorator_render_callback(self):
        """Test middleware with render callback."""
        from django.utils.decorators import make_middleware_decorator

        class RenderCallbackMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_template_response(self, request, response):
                return f"template_processed_{response}"

        decorator_factory = make_middleware_decorator(RenderCallbackMiddleware)
        decorator = decorator_factory()

        class RenderableResponse:
            def __init__(self, content):
                self.content = content
                self.callbacks = []

            def render(self):
                return self.content

            def add_post_render_callback(self, callback):
                self.callbacks.append(callback)

        def view_func(request):
            return RenderableResponse("rendered_content")

        decorated = decorator(view_func)
        response = decorated(None)
        # The callback should be added but not executed yet
        self.assertIsInstance(response, RenderableResponse)
        self.assertEqual(len(response.callbacks), 1)

