class JSONFieldTests(SimpleTestCase):
    """Tests for JSONField class."""

    def test_init_with_valid_encoder(self):
        encoder = lambda x: x
        f = JSONField(encoder=encoder)
        self.assertEqual(f.encoder, encoder)

    def test_init_with_invalid_encoder(self):
        with self.assertRaises(ValueError):
            JSONField(encoder="not_callable")

    def test_init_with_valid_decoder(self):
        decoder = lambda x: x
        f = JSONField(decoder=decoder)
        self.assertEqual(f.decoder, decoder)

    def test_init_with_invalid_decoder(self):
        with self.assertRaises(ValueError):
            JSONField(decoder="not_callable")

    def test_get_internal_type(self):
        f = JSONField()
        self.assertEqual(f.get_internal_type(), 'JSONField')

    def test_get_prep_value_none(self):
        f = JSONField()
        self.assertIsNone(f.get_prep_value(None))

    def test_get_prep_value_dict(self):
        f = JSONField()
        result = f.get_prep_value({'key': 'value'})
        self.assertIsInstance(result, str)
        self.assertIn('key', result)

    def test_get_prep_value_list(self):
        f = JSONField()
        result = f.get_prep_value([1, 2, 3])
        self.assertIsInstance(result, str)
        self.assertIn('1', result)

    def test_from_db_value_none(self):
        f = JSONField()
        result = f.from_db_value(None, None, None)
        self.assertIsNone(result)

    def test_from_db_value_string(self):
        f = JSONField()
        result = f.from_db_value('{"key": "value"}', None, None)
        self.assertIsInstance(result, dict)
        self.assertEqual(result['key'], 'value')

    def test_from_db_value_non_string_with_keytransform(self):
        from django.db.models.fields.json import KeyTransform
        f = JSONField()
        transform = KeyTransform('key', None)
        result = f.from_db_value(123, transform, None)
        self.assertEqual(result, 123)

    def test_from_db_value_invalid_json(self):
        f = JSONField()
        result = f.from_db_value('invalid json', None, None)
        self.assertEqual(result, 'invalid json')

    def test_validate_valid_json(self):
        f = JSONField()
        # Should not raise
        f.validate({'key': 'value'}, None)

    def test_validate_invalid_json(self):
        f = JSONField()
        with self.assertRaises(exceptions.ValidationError):
            f.validate(lambda x: x, None)

    def test_deconstruct_without_encoder_decoder(self):
        f = JSONField()
        name, path, args, kwargs = f.deconstruct()
        self.assertNotIn('encoder', kwargs)
        self.assertNotIn('decoder', kwargs)

    def test_deconstruct_with_encoder_decoder(self):
        encoder = lambda x: x
        decoder = lambda x: x
        f = JSONField(encoder=encoder, decoder=decoder)
        name, path, args, kwargs = f.deconstruct()
        self.assertIn('encoder', kwargs)
        self.assertIn('decoder', kwargs)

    def test_formfield(self):
        f = JSONField()
        form_field = f.formfield()
        self.assertIsNotNone(form_field)

    def test_empty_strings_allowed(self):
        f = JSONField()
        self.assertFalse(f.empty_strings_allowed)

    def test_description(self):
        f = JSONField()
        self.assertIsNotNone(f.description)


