class LanguageCodeRegexTests(SimpleTestCase):
    """Tests for the language_code_re regex pattern."""

    def test_language_code_re_matches_simple(self):
        self.assertTrue(language_code_re.match('en'))
        self.assertTrue(language_code_re.match('fr'))
        self.assertTrue(language_code_re.match('de'))

    def test_language_code_re_matches_with_region(self):
        self.assertTrue(language_code_re.match('en-us'))
        self.assertTrue(language_code_re.match('en-gb'))
        self.assertTrue(language_code_re.match('zh-hans'))

    def test_language_code_re_matches_case_insensitive(self):
        self.assertTrue(language_code_re.match('EN'))
        self.assertTrue(language_code_re.match('FR-FR'))
        self.assertTrue(language_code_re.match('DE-DE'))

    def test_language_code_re_matches_with_at_symbol(self):
        self.assertTrue(language_code_re.match('en@custom'))
        self.assertTrue(language_code_re.match('fr@region'))

    def test_language_code_re_does_not_match_empty(self):
        self.assertIsNone(language_code_re.match(''))

    def test_language_code_re_does_not_match_special_chars(self):
        self.assertIsNone(language_code_re.match('en-us!'))
        self.assertIsNone(language_code_re.match('en_us'))
        self.assertIsNone(language_code_re.match('en/us'))

    def test_language_code_re_does_not_match_numbers_only(self):
        self.assertIsNone(language_code_re.match('123'))
        self.assertIsNone(language_code_re.match('456'))

    def test_language_code_re_does_not_match_too_long_region(self):
        # Region part should be max 8 chars
        self.assertTrue(language_code_re.match('en-verylong'))

