class MockField(models.Field):
    """Mock field for testing."""
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.remote_field = None
        self.many_to_many = False

    def deconstruct(self):
        return ('django.db.models.CharField', [], {'max_length': 255})


class MockRemoteField:
    """Mock remote field for testing."""
    def __init__(self, model=None, through=None):
        self.model = model
        self.through = through


class MockModelMeta:
    """Mock model meta for testing."""
    managed = True
    proxy = False
    auto_created = False

    def get_field(self, name):
        return MockField()


class MockModel:
    """Mock model for testing."""
    _meta = MockModelMeta()

