from django.core.exceptions import ValidationError
from django.db import models, connection
from django.test import SimpleTestCase, TestCase
from django.test.utils import isolate_apps


@isolate_apps('invalid_models_tests')
class ModelInitTests(SimpleTestCase):
    """Test Model.__init__ method."""

    def test_init_with_no_args(self):
        class TestModel(models.Model):
            name = models.CharField(max_length=100)

        obj = TestModel()
        # CharField has empty string as default
        self.assertEqual(obj.name, '')

    def test_init_with_kwargs(self):
        class TestModel(models.Model):
            name = models.CharField(max_length=100)
            age = models.IntegerField()

        obj = TestModel(name="John", age=30)
        self.assertEqual(obj.name, "John")
        self.assertEqual(obj.age, 30)

    def test_init_unexpected_keyword_argument(self):
        class TestModel(models.Model):
            name = models.CharField(max_length=100)

        with self.assertRaises(TypeError) as cm:
            TestModel(invalid_arg=123)
        self.assertIn("unexpected keyword argument", str(cm.exception))

    def test_init_with_auto_field_pk(self):
        """Test that init works with auto-created primary key."""
        class TestModel(models.Model):
            name = models.CharField(max_length=100)

        obj = TestModel(name="John")
        self.assertEqual(obj.name, "John")
        # Auto PK starts as None until saved
        self.assertIsNone(obj.pk)


