class TestPrettyPrint:
    def test_pretty_print_short(self):
        from xarray.core.formatting import pretty_print
        result = pretty_print("hello", 10)
        assert len(result) == 10
        assert result == "hello     "

    def test_pretty_print_long(self):
        from xarray.core.formatting import pretty_print
        result = pretty_print("hello world", 5)
        assert len(result) == 5
        # When string is longer than numchars, it's truncated with ellipsis
        assert result.endswith("...") or result.startswith("he")


