class TestHelperFunctions(SimpleTestCase):
    """Tests for helper functions in checks.py"""

    def test_issubclass_valid_class(self):
        from django.contrib.admin.checks import _issubclass

        self.assertTrue(_issubclass(str, object))
        self.assertFalse(_issubclass(int, str))

    def test_issubclass_non_class(self):
        from django.contrib.admin.checks import _issubclass

        # Should not raise exception
        result = _issubclass("not a class", object)
        self.assertFalse(result)

    def test_contains_subclass_found(self):
        from django.contrib.admin.checks import _contains_subclass

        result = _contains_subclass(
            "django.contrib.auth.backends.ModelBackend",
            ["django.contrib.auth.backends.ModelBackend"],
        )
        self.assertTrue(result)

    def test_contains_subclass_subclass_found(self):
        from django.contrib.admin.checks import _contains_subclass

        class MyBackend:
            pass

        result = _contains_subclass(
            "django.contrib.auth.backends.ModelBackend",
            [MyBackend.__module__ + "." + MyBackend.__name__],
        )
        # This will be False since MyBackend is not a subclass
        self.assertFalse(result)


