class QuoteUnquoteTests(SimpleTestCase):
    def test_quote_basic(self):
        self.assertEqual(quote("hello"), "hello")

    def test_quote_slash(self):
        # quote() uses _XX format, not %XX
        self.assertEqual(quote("a/b"), "a_2Fb")

    def test_quote_underscore(self):
        self.assertEqual(quote("a_b"), "a_5Fb")

    def test_quote_colon(self):
        self.assertEqual(quote("a:b"), "a_3Ab")

    def test_quote_special_chars(self):
        result = quote('":/_#?;@&=+$,"[]<>%\n\\')
        self.assertIn('_3A', result)  # :
        self.assertIn('_2F', result)  # /

    def test_quote_non_string(self):
        self.assertEqual(quote(123), 123)
        self.assertEqual(quote(None), None)

    def test_unquote_basic(self):
        self.assertEqual(unquote("hello"), "hello")

    def test_unquote_encoded_slash(self):
        self.assertEqual(unquote("a_2Fb"), "a/b")

    def test_unquote_encoded_colon(self):
        self.assertEqual(unquote("a_3Ab"), "a:b")

    def test_unquote_multiple_encoded(self):
        self.assertEqual(unquote("a_2Fb_3Ac"), "a/b:c")


