# Test _try_repr_or_str function
class TestTryReprOrStr:
    def test_normal_object(self):
        result = _try_repr_or_str(42)
        assert result == "42"

    def test_string_object(self):
        result = _try_repr_or_str("hello")
        assert result == "'hello'"

