        result = _try_repr_or_str([1, 2, 3])
        assert result == "[1, 2, 3]"

    def test_dict_object(self):
        result = _try_repr_or_str({"a": 1})
        assert result == "{'a': 1}"

    def test_object_with_failing_repr_but_valid_str(self):
        """When repr fails but str works, str should be used."""
        class BadReprGoodStr:
            def __repr__(self):
                raise ValueError("Bad repr")
            def __str__(self):
                return "good_str"

        obj = BadReprGoodStr()
        result = _try_repr_or_str(obj)
        assert "BadReprGoodStr" in result
        assert "good_str" in result

