        obj = RaisesKI()
        with pytest.raises(KeyboardInterrupt):
            _try_repr_or_str(obj)

    def test_system_exit_propagated(self):
        class RaisesSE:
            def __repr__(self):
                raise SystemExit("test")

        obj = RaisesSE()
        with pytest.raises(SystemExit):
            _try_repr_or_str(obj)


# Test _format_repr_exception function
class TestFormatReprException:
    def test_basic_format(self):
        exc = ValueError("test error")
        obj = object()
        result = _format_repr_exception(exc, obj)
        assert "ValueError" in result
        assert "object" in result
        assert "0x" in result  # hex id

    def test_unpresentable_exception(self):
        class UnpresentableExc(Exception):
            def __repr__(self):
                raise RuntimeError("Cannot represent exception")

        exc = UnpresentableExc()
        obj = object()
        result = _format_repr_exception(exc, obj)
        # The exception itself might be unpresentable, so we check for the format
        assert "[" in result
        assert "]" in result

    def test_keyboard_interrupt_in_exc_repr_propagated(self):
        """KeyboardInterrupt raised when trying to repr the exception should propagate."""
        class BadExcRepr(Exception):
            def __repr__(self):
                raise KeyboardInterrupt("test")

        exc = BadExcRepr()
        obj = object()
        with pytest.raises(KeyboardInterrupt):
            _format_repr_exception(exc, obj)

    def test_system_exit_in_exc_repr_propagated(self):
        """SystemExit raised when trying to repr the exception should propagate."""
        class BadExcRepr(Exception):
            def __repr__(self):
                raise SystemExit("test")

        exc = BadExcRepr()
        obj = object()
        with pytest.raises(SystemExit):
            _format_repr_exception(exc, obj)

    def test_unpresentable_exception_handling(self):
        """Test when the exception's repr also fails."""
        class UnpresentableException(Exception):
            def __repr__(self):
                raise RuntimeError("Cannot represent this exception")

        exc = UnpresentableException()
        obj = object()
        result = _format_repr_exception(exc, obj)
        # Should handle the unpresentable exception gracefully
        assert "unpresentable" in result.lower() or "[" in result


