# Tests for construct_instance function
class ConstructInstanceTests(SimpleTestCase):
    def test_construct_instance_basic(self):
        """Test basic construction of instance from form data."""
        from django.forms.models import construct_instance

        person = TestPerson(name='John')

        class TestForm(ModelForm):
            class Meta:
                model = TestPerson
                fields = ['name']

            def clean(self):
                self.cleaned_data = {'name': 'Jane'}
                return super().clean()

        form = TestForm(instance=person)
        result = construct_instance(form, person)
        self.assertEqual(result.name, 'Jane')

    def test_construct_instance_with_auto_field(self):
        """Test that AutoField is skipped during construction."""
        from django.forms.models import construct_instance

        person = TestPerson(name='John')

        class TestForm(ModelForm):
            class Meta:
                model = TestPerson
                fields = ['name']

            def clean(self):
                self.cleaned_data = {'name': 'Jane'}
                return super().clean()

        form = TestForm(instance=person)
        result = construct_instance(form, person)
        # Should not raise an error when processing AutoField
        self.assertIsNotNone(result)


