class TestCoeffIsNeg(unittest.TestCase):
    """Tests for _coeff_isneg function."""

    def test_coeff_isneg_negative_number(self):
        assert _coeff_isneg(-3 * pi) is True

    def test_coeff_isneg_positive_number(self):
        assert _coeff_isneg(S(3)) is False

    def test_coeff_isneg_negative_oo(self):
        assert _coeff_isneg(-oo) is True

    def test_coeff_isneg_symbol_with_negative_assumption(self):
        n = Symbol('n', negative=True)
        assert _coeff_isneg(n) is False

    def test_coeff_isneg_matrix_expression_negative(self):
        A = MatrixSymbol("A", 3, 3)
        assert _coeff_isneg(-sqrt(2) * A) is True

