class TestFunction(unittest.TestCase):
    """Tests for Function class."""

    def test_function_creation(self):
        f = Function('f')
        self.assertEqual(f(x), f(x))

    def test_function_repr(self):
        f = Function('f')
        self.assertEqual(repr(f), 'f')

    def test_function_nargs_any(self):
        f = Function('f')
        from sympy.sets.fancysets import Naturals0
        self.assertEqual(f.nargs, Naturals0())

    def test_function_nargs_specific(self):
        f = Function('f', nargs=1)
        from sympy.sets.sets import FiniteSet
        self.assertEqual(f.nargs, FiniteSet(1))

    def test_function_nargs_multiple(self):
        f = Function('f', nargs=(2, 1))
        from sympy.sets.sets import FiniteSet
        self.assertEqual(f.nargs, FiniteSet(1, 2))

    def test_function_with_assumptions(self):
        f_real = Function('f', real=True)
        self.assertTrue(f_real(x).is_real)

    def test_function_inherit_assumptions_from_symbol(self):
        f = Function(Symbol('f', real=True))
        self.assertTrue(f(x).is_real)

    def test_function_eval_zero(self):
        class my_func(Function):
            @classmethod
            def eval(cls, x):
                if x.is_Number:
                    if x.is_zero:
                        return S.One
        self.assertEqual(my_func(0), S.One)

    def test_function_eval_infinity(self):
        class my_func(Function):
            @classmethod
            def eval(cls, x):
                if x.is_Number:
                    if x is S.Infinity:
                        return S.Zero
        self.assertEqual(my_func(oo), S.Zero)

    def test_function_diff_wrt(self):
        f = Function('f')
        # AppliedUndef has _diff_wrt = True
        self.assertTrue(f(x)._diff_wrt)

    def test_function_class_key(self):
        f = Function('f')
        key = f.class_key()
        self.assertIsInstance(key, tuple)

    def test_function_as_base_exp(self):
        f = Function('f')(x)
        base, exp = f.as_base_exp()
        self.assertEqual(base, f)
        self.assertEqual(exp, S.One)


