        self.assertIsNotNone(s)

    def test_subs_doit(self):
        s = Subs(x, x, 0)
        result = s.doit()
        self.assertEqual(result, 0)

    def test_subs_variables(self):
        s = Subs(x, x, 0)
        self.assertIn(x, s.variables)

    def test_subs_point(self):
        s = Subs(x, x, 0)
        self.assertIn(0, s.point)

    def test_subs_expr(self):
        s = Subs(x, x, 0)
        self.assertEqual(s.expr, x)

    def test_subs_free_symbols(self):
        # After substitution, free symbols may be empty
        s = Subs(x, x, 0)
        # The free_symbols property returns expr.free_symbols - variables + point.free_symbols
        # Since x is both in expr and variables, it cancels out
        self.assertIsInstance(s.free_symbols, set)

    def test_subs_eval_is_commutative(self):
        s = Subs(x, x, 0)
