class FunctionTests(SimpleTestCase):
    """Test the join function directly."""

    def test_join_list_of_strings(self):
        """Test joining a list of strings."""
        result = join(["a", "b", "c"], ", ")
        self.assertEqual(result, "a, b, c")

    def test_join_list_with_one_item(self):
        """Test joining a list with one item."""
        result = join(["single"], ", ")
        self.assertEqual(result, "single")

    def test_join_list_with_two_items(self):
        """Test joining a list with two items."""
        result = join(["first", "second"], "-")
        self.assertEqual(result, "first-second")

    def test_join_empty_list(self):
        """Test joining an empty list."""
        result = join([], ", ")
        self.assertEqual(result, "")

    def test_join_with_empty_separator(self):
        """Test joining with empty separator."""
        result = join(["a", "b", "c"], "")
        self.assertEqual(result, "abc")

    def test_join_with_none_values(self):
        """Test joining with None values (converted to strings)."""
        result = join([None, "b", None], "-")
        self.assertEqual(result, "None-b-None")

    def test_join_with_integer_values(self):
        """Test joining with integer values (converted to strings)."""
        result = join([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_join_with_mixed_types(self):
        """Test joining with mixed types."""
        result = join([1, "two", 3.0], "-")
        self.assertEqual(result, "1-two-3.0")

    def test_join_with_boolean_values(self):
        """Test joining with boolean values."""
        result = join([True, False, True], "|")
        self.assertEqual(result, "True|False|True")

    def test_join_with_dict_values(self):
        """Test joining with dict values."""
